from typing import List


class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        seen = set()
        for i in range(len(nums) - 1, -1, -1):
            if i + 1 < len(nums) and nums[i] == nums[i + 1]:
                return i // 3 + 1
            seen.add(nums[i])
        return 0

from typing import List


class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        seen = [False] * 100
        for i in range(len(nums) - 1, -1, -1):
            if seen[nums[i]]:
                return i // 3 + 1
            seen[nums[i]] = True
        return 0
